/**
 * Late enforcement. Generated by tools/generate_overlays.py from
 * tools/late_results/actions.json; do not edit.
 *
 * account.risk_changed only wakes the handler. handleRiskChange verifies the
 * delivery, reads the account's current risk (GET /v1/accounts/{account_id}),
 * asks your getAccountState where the account is in your own flow, and takes
 * the actions the table names for that state and the decision of its flow:
 *
 *   onboarding   account_creation review/block  fail_onboarding, revoke_sessions
 *   provisional  account_creation review/block  reject_activation, revoke_sessions
 *   active       login review                   revoke_sessions
 *   active       login block                    restrict, revoke_sessions
 *   restricted   login allow                    unrestrict, when flows.login.reinstate
 *
 * Every action, or none, is recorded with accounts.recordEnforcement at the
 * riskVersion read, and a refused action is recorded as failed and thrown.
 * No action deletes a user. The same table and vectors
 * (tests/fixtures/late-results-vectors.json) run in every SDK.
 */
import type { NoResponse } from "./client.js";
import type { Account } from "./models/account.js";
import type { EnforcementRequest } from "./models/enforcement-request.js";
import { NotFoundError } from "./models/errors/not-found-error.js";
import type { WebhookEvent } from "./models/webhook-event.js";
import { constructEvent, type ConstructEventOptions, type HeaderInput, type WebhookSecrets } from "./webhooks.js";

type Flow = "account_creation" | "login" | "purchase";
export type AccountState = "onboarding" | "provisional" | "active" | "restricted" | "rejected";
type EnforcementAction = "revoke_sessions" | "restrict" | "unrestrict" | "fail_onboarding" | "reject_activation" | "none";
/** An action a provider runs: every EnforcementAction but none. */
export type ProviderAction = Exclude<EnforcementAction, "none">;

type Request = { method: string; path: string; query?: Record<string, string>; body?: unknown };
type Step = {
  call: Request;
  each?: { list: Request; page: { kind: "offset" | "index" | "cursor"; param: string; size?: number; next?: string[] }; where?: Record<string, unknown> };
  fallback?: { status: number; code: string; reports?: ProviderAction; steps: Step[] };
};
type Rule = { flow: Flow; on: Partial<Record<string, ProviderAction[]>>; reinstate?: Partial<Record<string, ProviderAction[]>> };
type Table = {
  lifecycle: Record<AccountState, Rule>;
  providers: Record<string, { base_url: string; actions: Record<ProviderAction, Step[]> }>;
  limits: { retries: number; budget_ms: number; backoff_ms: number; max_pages: number };
};

const TABLE: Table = {"lifecycle":{"onboarding":{"flow":"account_creation","on":{"review":["fail_onboarding","revoke_sessions"],"block":["fail_onboarding","revoke_sessions"]}},"provisional":{"flow":"account_creation","on":{"review":["reject_activation","revoke_sessions"],"block":["reject_activation","revoke_sessions"]}},"active":{"flow":"login","on":{"review":["revoke_sessions"],"block":["restrict","revoke_sessions"]}},"restricted":{"flow":"login","on":{},"reinstate":{"allow":["unrestrict"]}},"rejected":{"flow":"account_creation","on":{}}},"providers":{"clerk":{"base_url":"https://api.clerk.com/v1","actions":{"fail_onboarding":[{"call":{"method":"POST","path":"/users/{user}/ban"}}],"reject_activation":[{"call":{"method":"POST","path":"/users/{user}/ban"}}],"restrict":[{"call":{"method":"POST","path":"/users/{user}/ban"}}],"unrestrict":[{"call":{"method":"POST","path":"/users/{user}/unban"}}],"revoke_sessions":[{"each":{"list":{"method":"GET","path":"/sessions","query":{"user_id":"{user}","status":"active","limit":"100"}},"page":{"kind":"offset","param":"offset","size":100},"where":{"status":"active"}},"call":{"method":"POST","path":"/sessions/{item}/revoke"}}]}},"workos":{"base_url":"https://api.workos.com","actions":{"fail_onboarding":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":"onboarding_failed"}}}}],"reject_activation":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":"activation_rejected"}}}}],"restrict":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":"restricted"}}}}],"unrestrict":[{"call":{"method":"PUT","path":"/user_management/users/{user}","body":{"metadata":{"noresponse_state":null}}}}],"revoke_sessions":[{"each":{"list":{"method":"GET","path":"/user_management/users/{user}/sessions","query":{"limit":"100"}},"page":{"kind":"cursor","param":"after","next":["list_metadata","after"]},"where":{"status":"active"}},"call":{"method":"POST","path":"/user_management/sessions/revoke","body":{"session_id":"{item}"}}}]}},"auth0":{"base_url":"https://{domain}/api/v2","actions":{"fail_onboarding":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}],"reject_activation":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}],"restrict":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}],"unrestrict":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":false}}}],"revoke_sessions":[{"call":{"method":"DELETE","path":"/users/{user}/sessions"},"fallback":{"status":403,"code":"feature_not_enabled","reports":"restrict","steps":[{"call":{"method":"PATCH","path":"/users/{user}","body":{"blocked":true}}}]}},{"call":{"method":"DELETE","path":"/users/{user}/refresh-tokens"},"fallback":{"status":403,"code":"feature_not_enabled","steps":[{"each":{"list":{"method":"GET","path":"/device-credentials","query":{"user_id":"{user}","type":"refresh_token","per_page":"100"}},"page":{"kind":"index","param":"page","size":100}},"call":{"method":"DELETE","path":"/device-credentials/{item}"}},{"each":{"list":{"method":"GET","path":"/device-credentials","query":{"user_id":"{user}","type":"rotating_refresh_token","per_page":"100"}},"page":{"kind":"index","param":"page","size":100}},"call":{"method":"DELETE","path":"/device-credentials/{item}"}}]}}]}}},"limits":{"retries":4,"budget_ms":3000,"backoff_ms":250,"max_pages":100}} as Table;
/** Every action a provider runs, as the table names them. */
const ACTIONS: ReadonlySet<string> = new Set(Object.values(TABLE.providers).flatMap((provider) => Object.keys(provider.actions)));
/** Each admin API call gives up after this long; the provider then counts as unreachable. */
const REQUEST_TIMEOUT_MS = 10_000;

/** Where the account is in your flow, from getAccountState. */
export type AccountStateAnswer = {
  state: AccountState;
  /** The provider's user id. Defaults to the account id, as when you assess with the provider's user id. */
  userId?: string;
  /** The riskVersion you last enforced (a result's riskVersion that you stored). An account at or below it is skipped. */
  enforcedRiskVersion?: number;
};

/** Runs one action in an identity provider. Build one with identityProvider or customProvider. */
export interface ActionProvider {
  readonly name: "clerk" | "workos" | "auth0" | "custom";
  /** Take the action and return any other action that had to run with it (Auth0 restricts to end a session). */
  run(action: ProviderAction, userId: string): Promise<ProviderAction[]>;
}

export type FlowPolicy = {
  /** Lift a restriction once the flow's decision is allow again. Off by default. */
  reinstate?: boolean;
};

export type EnforcementOptions = ConstructEventOptions & {
  provider: ActionProvider;
  /** The account's state in your flow; null or undefined for an account you do not hold. */
  getAccountState: (account: Account) => AccountStateAnswer | null | undefined | Promise<AccountStateAnswer | null | undefined>;
  flows?: Partial<Record<Flow, FlowPolicy>>;
};

/** Why nothing was done: not account.risk_changed (or a test event), the account was erased, getAccountState knows no such account, or its riskVersion is already enforced. */
export type EnforcementSkip = "not_actionable" | "account_gone" | "unknown_user" | "already_enforced";

export type Enforced = { flow: Flow; action: EnforcementAction; status: "applied" | "failed"; errorCode?: string };

export type EnforcementResult = {
  /** The verified event, from handleRiskChange. Answer an endpoint.verification with its challenge. */
  event?: WebhookEvent;
  account?: Account;
  state?: AccountState;
  /** The riskVersion acted on. Store it and return it as enforcedRiskVersion. */
  riskVersion?: number;
  skipped?: EnforcementSkip;
  /** What was recorded, in order. */
  enforcements: Enforced[];
};

/** The provider refused an action or could not be reached (status 0). Answer the webhook with a 5xx so it is delivered again. */
export class ProviderActionError extends Error {
  readonly provider: string;
  readonly status: number;
  /** The provider's error code, such as Auth0's errorCode "insufficient_scope", when it sent one. */
  readonly code: string | undefined;
  constructor(provider: string, status: number, message: string, code?: string) {
    super(message);
    this.name = "ProviderActionError";
    this.provider = provider;
    this.status = status;
    this.code = code;
  }
}

/**
 * Verify an account.risk_changed delivery and enforce the account's current
 * risk. A delivery that fails verification throws WebhookVerificationError
 * before anything is read; any other event, and a test event, does nothing.
 */
export async function handleRiskChange(
  client: NoResponse,
  payload: Uint8Array | string,
  headers: HeaderInput,
  secrets: WebhookSecrets,
  options: EnforcementOptions,
): Promise<EnforcementResult> {
  const { provider: _provider, getAccountState: _getAccountState, flows: _flows, ...verify } = options;
  const event = await constructEvent(payload, headers, secrets, verify);
  if (event.type !== "account.risk_changed" || (event as { test?: boolean }).test === true) {
    return { event, skipped: "not_actionable", enforcements: [] };
  }
  let account: Account;
  try {
    account = await client.accounts.get(event.data.account.id);
  } catch (error) {
    if (error instanceof NotFoundError) return { event, skipped: "account_gone", enforcements: [] };
    throw error;
  }
  return { event, ...(await enforceAccount(client, account, options)) };
}

const FLOW_KEYS = { account_creation: "accountCreation", login: "login", purchase: "purchase" } as const;

/**
 * Enforce one account as read: the account a handler fetched, or one from
 * accounts.listChanged({ unenforced: true }) when catching up.
 */
export async function enforceAccount(client: NoResponse, account: Account, options: EnforcementOptions): Promise<EnforcementResult> {
  const answer = await options.getAccountState(account);
  if (!answer) return { account, skipped: "unknown_user", enforcements: [] };
  const { state } = answer;
  const rule = TABLE.lifecycle[state];
  if (!rule) throw new TypeError(`unknown account state ${String(state)}`);
  const riskVersion = account.riskVersion;
  if (answer.enforcedRiskVersion !== undefined && riskVersion <= answer.enforcedRiskVersion) {
    return { account, state, riskVersion, skipped: "already_enforced", enforcements: [] };
  }
  const { flow } = rule;
  const decision: string = account.decisionsByFlow[FLOW_KEYS[flow]];
  const actions = rule.on[decision] ?? (options.flows?.[flow]?.reinstate ? rule.reinstate?.[decision] : undefined) ?? [];
  const provider = options.provider;
  const enforcements: Enforced[] = [];
  const record = async (action: EnforcementAction, status: Enforced["status"], errorCode?: string) => {
    const body = { riskVersion, flow, action, stateBefore: state, status, provider: provider.name, ...(errorCode ? { errorCode } : {}) };
    await client.accounts.recordEnforcement(account.id, body as EnforcementRequest);
    enforcements.push({ flow, action, status, ...(errorCode ? { errorCode } : {}) });
  };
  if (actions.length === 0) {
    // An adverse or step_up decision that needs nothing still counts as handled.
    if (decision !== "allow") await record("none", "applied");
    return { account, state, riskVersion, enforcements };
  }
  const recorded = new Set<EnforcementAction>();
  for (const action of actions) {
    let alsoRan: ProviderAction[];
    try {
      alsoRan = await provider.run(action, answer.userId || account.id);
    } catch (error) {
      await record(action, "failed", failureCode(provider.name, error));
      throw error;
    }
    for (const ran of [...alsoRan, action]) {
      if (recorded.has(ran)) continue;
      recorded.add(ran);
      await record(ran, "applied");
    }
  }
  return { account, state, riskVersion, enforcements };
}

const SLUG = /^[a-z0-9_.-]+$/;

/** The error_code of a failed action: the provider's code, else its HTTP status, as <provider>.<code>. */
function failureCode(provider: string, error: unknown): string {
  const code = (error as { code?: unknown } | null)?.code;
  const status = error instanceof ProviderActionError ? error.status : undefined;
  const suffix = typeof code === "string" && SLUG.test(code.toLowerCase())
    ? code.toLowerCase()
    : status === 0 ? "unreachable" : status !== undefined ? `http_${status}` : "error";
  return `${provider}.${suffix}`.slice(0, 128);
}

type Fetch = typeof fetch;

export type IdentityProviderOptions = {
  /** Clerk secret key, WorkOS API key or Auth0 Management API token. */
  token: string;
  /** Auth0 tenant domain, such as example.eu.auth0.com. */
  domain?: string;
  /** The admin API's base URL, in place of the table's (or of domain). */
  baseUrl?: string;
  fetch?: Fetch;
};

/** Clerk, WorkOS or Auth0, run from the shared action table. */
export function identityProvider(name: "clerk" | "workos" | "auth0", options: IdentityProviderOptions): ActionProvider {
  const spec = TABLE.providers[name];
  if (!spec) throw new TypeError(`unknown identity provider ${String(name)}`);
  if (!options?.token) throw new TypeError(`${name} needs token`);
  let base = options.baseUrl ?? spec.base_url;
  if (base.includes("{domain}")) {
    if (!options.domain) throw new TypeError(`${name} needs domain or baseUrl`);
    base = base.replace("{domain}", options.domain);
  }
  const http = { name, base: base.replace(/\/+$/, ""), authorization: `Bearer ${options.token}`, fetch: options.fetch ?? globalThis.fetch };
  return {
    name,
    async run(action, userId) {
      if (typeof userId !== "string" || userId === "") throw new TypeError("user id must be a non-empty string");
      const steps = spec.actions[action];
      if (!steps) throw new TypeError(`unknown action ${String(action)}`);
      return runSteps(steps, { ...http, user: userId, waitedMs: 0 });
    },
  };
}

/** Your own user store: one function per action you support. An action without one fails. */
export function customProvider(handlers: Partial<Record<ProviderAction, (userId: string) => Promise<void | ProviderAction[]>>>): ActionProvider {
  return {
    name: "custom",
    async run(action, userId) {
      const handler = handlers[action];
      if (!handler) throw new TypeError(`customProvider has no ${action} handler`);
      const alsoRan: unknown = await handler(userId);
      // Only a list of action names counts; any other return value is no extra action.
      return Array.isArray(alsoRan) ? alsoRan.filter((name): name is ProviderAction => typeof name === "string" && ACTIONS.has(name)) : [];
    },
  };
}

type Context = { name: string; base: string; authorization: string; fetch: Fetch; user: string; waitedMs: number };

async function runSteps(steps: Step[], ctx: Context): Promise<ProviderAction[]> {
  const alsoRan: ProviderAction[] = [];
  for (const step of steps) {
    if (step.each) {
      for (const item of await collect(step.each, ctx)) await send(step.call, ctx, item);
      continue;
    }
    try {
      await send(step.call, ctx);
    } catch (error) {
      const fallback = step.fallback;
      if (!fallback || !(error instanceof ProviderActionError) || error.status !== fallback.status || error.code !== fallback.code) throw error;
      alsoRan.push(...(await runSteps(fallback.steps, ctx)));
      if (fallback.reports) alsoRan.push(fallback.reports);
    }
  }
  return alsoRan;
}

/** Every matching item id across the list's pages, collected before any is acted on. */
async function collect(each: NonNullable<Step["each"]>, ctx: Context): Promise<string[]> {
  const { list, page, where } = each;
  const ids: string[] = [];
  let cursor: string | undefined;
  for (let index = 0; index < TABLE.limits.max_pages; index++) {
    const query = { ...list.query };
    if (page.kind === "offset") query[page.param] = String(index * (page.size ?? 0));
    else if (page.kind === "index") query[page.param] = String(index);
    else if (cursor !== undefined) query[page.param] = cursor;
    const body = await send({ ...list, query }, ctx);
    const data = (body as { data?: unknown } | undefined)?.data;
    const items: unknown[] = Array.isArray(body) ? body : Array.isArray(data) ? data : [];
    for (const item of items) {
      const record = item as Record<string, unknown> | null;
      const id = record?.["id"];
      if (typeof id !== "string" || id === "") continue;
      if (Object.entries(where ?? {}).every(([key, value]) => record?.[key] === value)) ids.push(id);
    }
    if (page.kind === "cursor") {
      let next: unknown = body;
      for (const key of page.next ?? []) next = (next as Record<string, unknown> | null | undefined)?.[key];
      if (typeof next !== "string" || next === "") break;
      cursor = next;
    } else if (items.length < (page.size ?? 0)) break;
  }
  return ids;
}

function fill(value: unknown, user: string, item: string | undefined): unknown {
  if (typeof value === "string") return value.replaceAll("{user}", user).replaceAll("{item}", item ?? "");
  if (Array.isArray(value)) return value.map((entry) => fill(entry, user, item));
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, fill(entry, user, item)]));
  }
  return value;
}

const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

/** How long a 429 asks to wait, in milliseconds. */
function rateLimitWaitMs(headers: Headers, retry: number): number {
  const after = headers.get("retry-after")?.trim();
  if (after) {
    const seconds = Number(after);
    if (Number.isFinite(seconds) && seconds >= 0) return seconds * 1000;
  }
  const reset = headers.get("x-ratelimit-reset")?.trim();
  if (reset) {
    const at = Number(reset);
    if (Number.isFinite(at)) return Math.max(0, at * 1000 - Date.now());
  }
  return TABLE.limits.backoff_ms * 2 ** retry;
}

/** The provider's error code: Auth0's errorCode, WorkOS's code or Clerk's errors[0].code. */
function errorCode(text: string): string | undefined {
  try {
    const body = JSON.parse(text) as { errorCode?: unknown; code?: unknown; errors?: Array<{ code?: unknown }> } | null;
    const code = body?.errorCode ?? body?.code ?? body?.errors?.[0]?.code;
    return typeof code === "string" && code !== "" ? code : undefined;
  } catch {
    return undefined;
  }
}

/** One admin API call. A 404 is done (undefined); a 429 is waited out inside the action's budget; any other failure throws. */
async function send(request: Request, ctx: Context, item?: string): Promise<unknown> {
  const path = request.path.replaceAll("{user}", encodeURIComponent(ctx.user)).replaceAll("{item}", encodeURIComponent(item ?? ""));
  const url = new URL(ctx.base + path);
  for (const [key, value] of Object.entries(request.query ?? {})) url.searchParams.set(key, fill(value, ctx.user, item) as string);
  const headers: Record<string, string> = { authorization: ctx.authorization, accept: "application/json" };
  const body = request.body === undefined ? undefined : JSON.stringify(fill(request.body, ctx.user, item));
  if (body !== undefined) headers["content-type"] = "application/json";
  const label = `${ctx.name} ${request.method} ${request.path}`;
  for (let retry = 0; ; retry++) {
    let response: Response;
    try {
      response = await ctx.fetch(url, {
        method: request.method,
        headers,
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
        ...(body !== undefined ? { body } : {}),
      });
    } catch (error) {
      throw new ProviderActionError(ctx.name, 0, `${label} failed: ${(error as Error)?.message ?? String(error)}`);
    }
    const text = await response.text();
    if (response.status === 429 && retry < TABLE.limits.retries) {
      const wait = rateLimitWaitMs(response.headers, retry);
      if (ctx.waitedMs + wait <= TABLE.limits.budget_ms) {
        ctx.waitedMs += wait;
        await sleep(wait);
        continue;
      }
    }
    if (response.status === 404) return undefined;
    if (!response.ok) throw new ProviderActionError(ctx.name, response.status, `${label} answered ${response.status}`, errorCode(text));
    if (!text) return undefined;
    try {
      return JSON.parse(text);
    } catch {
      return undefined;
    }
  }
}
